<script>
// Importar las imágenes como assets con Vite
import banner1 from "../../../images/banners/banner_1.webp";
import banner2 from "../../../images/banners/banner_2.webp";
import banner3 from "../../../images/banners/banner_3.webp";
import banner4 from "../../../images/banners/banner_4.webp";
import banner5 from "../../../images/banners/banner_5.webp";

export default {
    name: "CoursesSection",
    data() {
        return {
            currentBanner: 0,
            banners: [banner1, banner2, banner3, banner4, banner5],
            autoPlayInterval: null,
        };
    },
    mounted() {
        this.startAutoPlay();
    },
    beforeUnmount() {
        this.stopAutoPlay();
    },
    methods: {
        startAutoPlay() {
            this.autoPlayInterval = setInterval(() => {
                this.nextBanner();
            }, 5000); // Cambia cada 5 segundos
        },
        stopAutoPlay() {
            if (this.autoPlayInterval) {
                clearInterval(this.autoPlayInterval);
            }
        },
        nextBanner() {
            this.currentBanner = (this.currentBanner + 1) % this.banners.length;
        },
        setBanner(index) {
            this.currentBanner = index;
            this.stopAutoPlay();
            this.startAutoPlay(); // Reinicia el auto-play
        },
    },
};
</script>

